mapper.select:
/** InterfaceMapperVE.selectReturnOrderInfo : 반품처리할 오더 데이터 조회 **/
SELECT *
FROM TB_ECM_OD OD
WHERE OD.ENT_CODE = #{entCode}
AND OD.PO_NO = #{orderId}

/** InterfaceMapperVE.selectReturnOrderInfoPop : 반품처리할 오더 데이터 조회(팝업에서)**/
SELECT *
FROM TB_ECM_OD OD
WHERE OD.ENT_CODE = #{entCode}
  AND OD.OD_JOB_NO = #{odJobNo}

/** InterfaceMapperVE.selectReturnChk : 반품처리할 오더 데이터 반품id **/
SELECT
	RETURN_REQUEST_ID
FROM
	TB_ECM_OD_MULTI
WHERE
	OD_JOB_NO = #{odJobNo}

	AND DELIVERY_NO = #{multiDeliveryNo}
	AND SEQ_NO_ID = #{seqNoId}

mapper.update:
/** InterfaceMapperVE.updateReturnOrder : 반품처리할 오더 데이터 수정 **/
UPDATE TB_ECM_OD SET
	RETURN_YN = 'Y'
WHERE PO_NO = #{orderId}

/** InterfaceMapperVE.updateReturnOrderAd : 반품처리 requestId 수정 **/
UPDATE TB_ECM_OD_ADDITIONAL SET
	RETURN_REQUEST_ID = #{requestId}
	,RETURN_REQ_DATE = GETDATE()
WHERE OD_JOB_NO IN (SELECT OD_JOB_NO FROM TB_ECM_OD WHERE PO_NO = #{orderId})

/** InterfaceMapperVE.updateReturnOrderJob : 반품처리할 오더 데이터 수정(잡넘버기준) **/
UPDATE TB_ECM_OD SET
	RETURN_YN = 'Y'
WHERE OD_JOB_NO = #{odJobNo}

/** InterfaceMapperVE.updateReturnOrderAdJob : 반품처리 requestId 수정(잡넘버기준) **/
UPDATE TB_ECM_OD_ADDITIONAL SET
	RETURN_REQUEST_ID = #{returnRequestId}
	,RETURN_DELIVERY_CODE = #{returnDeliveryCode}
  ,RETURN_REQ_DATE = GETDATE()
WHERE OD_JOB_NO = #{odJobNo}

mapper.insert:
/** InterfaceMapperVE.insertReturninfo : 반품정보 저장 **/
INSERT INTO TB_ECM_OD_RETURN_INFO (
			OD_JOB_NO
		  ,REQUEST_ID
		  ,SENDER_ZIPCODE
		  ,SENDER_NAME
		  ,SENDER_TEL
		  ,SENDER_HP
		  ,SENDER_ADDRESS
		  ,SENDER_ADDRESS_DETAIL
		  ,RECEIVER_ZIPCODE
		  ,RECEIVER_NAME
		  ,RECEIVER_TEL
		  ,RECEIVER_HP
		  ,RECEIVER_ADDRESS
		  ,RECEIVER_ADDRESS_DETAIL
		  ,REGISTER_USER_ID
		  ,REGISTER_DATE_TIME
		  ,UPDATE_USER_ID
		  ,UPDATE_DATE_TIME
) VALUES (
		   #{od_job_no}
		 ,#{requestId}
		 ,#{senderZipcode}
		 ,#{senderName}
		 ,#{senderTel}
		 ,#{senderHp}
		 ,#{senderAddress}
		 ,#{senderAddressDetail}
		 ,#{receiverZipcode}
		 ,#{receiverName}
		 ,#{receiverTel}
		 ,#{receiverHp}
		 ,#{receiverAddress}
		 ,#{receiverAddressDetail}
		 ,'API'
		 ,GETDATE()
		 ,'API'
		 ,GETDATE()
		 )

mapper.update:
/** InterfaceMapperVE.updateCustomsCancelInfo : 개인통관부호 검증 취소 저장 **/
MERGE INTO TB_ECM_CUSTOMS_ID_INFO AS A
USING (SELECT #{requestId} AS REQUEST_ID) AS B
ON (A.REQUEST_ID = B.REQUEST_ID)
WHEN MATCHED THEN
UPDATE SET
	STATUS = '01'	 
	,UPDATE_USER_ID = 'API'
	,UPDATE_DATE_TIME = GETDATE()
WHEN NOT MATCHED THEN
INSERT(
	CUSTOMS_ID_JOB_NO
	,ENT_CODE
	,REQUEST_ID
	,PO_NO
	,ORIG_CUSTOMS_ID
	,ORIG_CONSIGNEE_NAME
	,ORIG_CONSIGNEE_HP
	,ORIG_CONSIGNEE_ZIPCODE
	,INPUT_METHOD
	,STATUS
	,COMMODITY_ITEM
	,CONSIGNEE_ADDRESS
	,REGISTER_USER_ID
	,REGISTER_DATE_TIME
	,UPDATE_USER_ID
	,UPDATE_DATE_TIME
)
VALUES (
	#{customsIdJobNo}
	,#{entCode}
	,#{requestId}
	,#{poNo}
	,#{customsId}
	,#{consigneeName}
	,#{consigneeHp}
	,#{consigneeZipcode}
	,#{inputMethod}
	,'01'
	,#{commodityItem}
	,#{consigneeAddress}
	,'API'
	,GETDATE()
	,'API'
	,GETDATE()
);

mapper.delete:
/* InterfaceMapperVE.deleteReturninfo : 변경시 반품이력삭제 */
DELETE FROM TB_ECM_OD_RETURN_INFO
WHERE OD_JOB_NO = #{od_job_no}

mapper.select:
/** InterfaceMapperVE.selectDupReqId : 중복데이터 오더 데이터 조회 **/
SELECT COUNT(*)
FROM TB_ECM_CUSTOMS_ID_INFO 
WHERE REQUEST_ID = #{requestId}

AND STATUS = '01'

mapper.update:
/* InterfaceMapperVE.insertReturnMulti : 반품용멀티등록 */
INSERT INTO TB_ECM_OD_MULTI(
		 OD_JOB_NO
	   ,SEQ_NO_ID
	   ,DELIVERY_NO
	   ,DELIVERY_CODE
	   ,CUSTOMER_CODE
	   ,PAYMENT_GUBN
	   ,DELIVERY_FEE
	   ,PIECES
	   ,DIM_WIDTH
	   ,DIM_LENGTH
	   ,DIM_HEIGHT
	   ,VWT
	   ,RECIPIENT_NAME
	   ,REMARKS
	   ,RETURN_REQUEST_ID
	   ,REGISTER_USER_ID
	   ,RETURN_DELIVERY_CODE
	   ,REGISTER_DATE_TIME
	   ,RETURN_REQ_DATE
)VALUES(
		 #{odJobNo}
	   ,(SELECT ISNULL(MAX(SEQ_NO_ID), 0) + 1 FROM TB_ECM_OD_MULTI WHERE OD_JOB_NO = #{odJobNo})
	   ,#{deliveryNo}
	   ,#{deliveryCode}
	   ,#{customerCode}
	   ,#{paymentGubn}
	   ,#{deliveryFee}
	   ,#{pieces}
	   ,#{dimWidth}
	   ,#{dimLength}
	   ,#{dimHeight}
	   ,#{vwt}
	   ,#{recipientName}
	   ,#{remarks}
	   ,#{requestId}
	   ,#{registerUserId}
	   ,#{returnDeliveryCode}
	   ,GETDATE()
	   ,GETDATE()
	   )

/* InterfaceMapperVE.updateReturnMulti : 반품용멀티업데이트 */
UPDATE TB_ECM_OD_MULTI SET
	RETURN_REQUEST_ID = #{requestId}
	,RETURN_DELIVERY_CODE = #{returnDeliveryCode}
	,RETURN_REQ_DATE = GETDATE()
	,UPDATE_USER_ID = #{registerUserId}
	,UPDATE_DATE_TIME = GETDATE()
WHERE OD_JOB_NO = #{odJobNo}
AND DELIVERY_NO = #{multiDeliveryNo}
AND SEQ_NO_ID = #{seqNoId}

mapper.select:
/* InterfaceMapperVE.selectReturnMultiSeqNoId : 방금 등록한 반품용 멀티건 SEQ_NO_ID 조회 */
SELECT MAX(SEQ_NO_ID)
FROM TB_ECM_OD_MULTI
WHERE OD_JOB_NO = #{odJobNo}
AND RETURN_REQUEST_ID = #{requestId}

mapper.insert:
/* InterfaceMapperVE.insertReturnResendInfo : 반품관리 조회용 RESEND_INFO 등록 */
INSERT INTO TB_ECM_OD_RESEND_INFO(
	   OD_JOB_NO
	  ,SEQ_NO_ID
	  ,INPUT_METHOD
	  ,REGISTER_USER_ID
	  ,REGISTER_DATE_TIME
	  ,UPDATE_USER_ID
	  ,UPDATE_DATE_TIME
)VALUES(
	   #{odJobNo}
	  ,#{seqNoId}
	  ,'CS'
	  ,#{registerUserId}
	  ,GETDATE()
	  ,#{registerUserId}
	  ,GETDATE()
)

/** InterfaceMapperVE.insertCustomsInfo : PCCC 정보 추가 **/
INSERT TB_ECM_CUSTOMS_ID_INFO(
	CUSTOMS_ID_JOB_NO
	,ENT_CODE
	,CUST_CODE_LV1
	,REQUEST_ID
	,PO_NO
	,HBL_NO
	,ORIG_CUSTOMS_ID
	,ORIG_CONSIGNEE_NAME
	,ORIG_CONSIGNEE_HP
	,ORIG_CONSIGNEE_ZIPCODE
	,PO_DATE_TIME
	,PO_NAME
	,INPUT_METHOD
	,COMMODITY_ITEM
	,CONSIGNEE_ADDRESS
	,REGISTER_USER_ID
	,REGISTER_DATE_TIME
	,UPDATE_USER_ID
	,UPDATE_DATE_TIME
)
VALUES (
	#{customsIdJobNo}
	,#{entCode}
	,#{custCodeLv1}
	,#{requestId}
	,#{poNo}
	,#{hblNo}
	,#{customsId}
	,#{consigneeName}
	,#{consigneeHp}
	,#{consigneeZipcode}
	,CONVERT(VARCHAR(19), #{poDate}, 120)
	,#{poName}
	,#{inputMethod}
	,#{commodityItem}
	,#{consigneeAddress}
	,'API'
	,GETDATE()
	,'API'
	,GETDATE()
);
